----------------光效-------------------------------------------------------	local tCarnival2016_Food_Effect = {}	tCarnival2016_Food_Effect["Self"] = "self"	tCarnival2016_Food_Effect[3000454] = "butterfly"	tCarnival2016_Food_Effect[3000455] = ""	tCarnival2016_Food_Effect[3000456] = "angelwing"	tCarnival2016_Food_Effect[3000457] = "zf2-e105"	tCarnival2016_Food_Effect[3000458] = "angelwing"	tCarnival2016_Food_Effect[3000459] = "angelwing"	tCarnival2016_Food_Effect[3000460] = ""	tCarnival2016_Food_Effect[3000461] = ""	tCarnival2016_Food_Effect[3000462] = "angelwing"		------------------------------------------------------LOG-------------------------------------------------------	local tCarnival2016_Food_Log = {}		tCarnival2016_Food_Log["Id"] = 10001515	tCarnival2016_Food_Log["FestivalId"] = 3373			tCarnival2016_Food_Log["TimeDel"] = "0,0,%d,1,10001515,2,0,0"	------------------------------------------------------逻辑部分-------------------------------------------------------选项名：谢谢。--功能呢：玩家可以领取礼物后，点谢谢得到奖励function Carnival2016_Food_GetFestivalPack(nNpcId)	--活动时间前	if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-1")		return	end		--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-4")		return	end		--等级不满足	if not User_JudgeLevelAndMetempsychosis(tCarnival2016_Food_Cont["MinLevel"],tCarnival2016_Food_Cont["MinMete"]) then		LinkNpcGossipFunc_New(nNpcId,"1-3")		return	end		local nEventAward = tCarnival2016_Food_Stc[1]["Event"]	local nTypeAward = tCarnival2016_Food_Stc[1]["Type"]		if Task_ChkStcValue(nEventAward,nTypeAward,"==",1) then		if Task_StcInterval(nEventAward,nTypeAward,1,4) then			Task_SetStatistic(nEventAward,nTypeAward,0,1)		end	end		--已经领取过礼物了	if Task_ChkStcValue(nEventAward,nTypeAward,"==",1) then		LinkNpcGossipFunc_New(nNpcId,"2-5")		return	end		--没有全部猜对	if not Carnival2016_Food_ChkAllGuess() then		LinkNpcGossipFunc_New(nNpcId,"2-2")		return	end		--背包空间不足	if not User_CheckLeftSpace(1) then		LinkNpcGossipFunc_New(nNpcId,"2-4")		return	end		Task_SetStatistic(nEventAward,nTypeAward,1,1)	Task_SetStcTimestamp(nEventAward,nTypeAward,0)		FestivalGeneralPackage_GetGift(tCarnival2016_Food_Log["FestivalId"],tCarnival2016_Food_Log["Id"])		end--选项名：我来领礼物。--功能：玩家在其他3个npc猜中食物后，可在此领取奖励function Carnival2016_Food_GetGift(nNpcId)		--活动时间前	if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-1")		return	end		--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-4")		return	end		--等级不满足	if not User_JudgeLevelAndMetempsychosis(tCarnival2016_Food_Cont["MinLevel"],tCarnival2016_Food_Cont["MinMete"]) then		LinkNpcGossipFunc_New(nNpcId,"1-3")		return	end		local nEventAward = tCarnival2016_Food_Stc[1]["Event"]	local nTypeAward = tCarnival2016_Food_Stc[1]["Type"]		if Task_ChkStcValue(nEventAward,nTypeAward,"==",1) then		if Task_StcInterval(nEventAward,nTypeAward,1,4) then			Task_SetStatistic(nEventAward,nTypeAward,0,1)		end	end		--已经领取过礼物了	if Task_ChkStcValue(nEventAward,nTypeAward,"==",1) then		LinkNpcGossipFunc_New(nNpcId,"2-5")		return	end		--没有全部猜对	if not Carnival2016_Food_ChkAllGuess() then		LinkNpcGossipFunc_New(nNpcId,"2-2")		return	end		--背包空间不足	if not User_CheckLeftSpace(1) then		LinkNpcGossipFunc_New(nNpcId,"2-4")		return	end		LinkNpcGossipFunc_New(nNpcId,"2-3")	end--判断今天在三个npc处是否全部猜对--全部猜对返回true，没有则返回faslefunction Carnival2016_Food_ChkAllGuess()		local nEventGuess1 = tCarnival2016_Food_Stc[5]["Event"]	local nTypeGuess1= tCarnival2016_Food_Stc[5]["Type"]		local nEventGuess2 = tCarnival2016_Food_Stc[6]["Event"]	local nTypeGuess2= tCarnival2016_Food_Stc[6]["Type"]		local nEventGuess3 = tCarnival2016_Food_Stc[7]["Event"]	local nTypeGuess3= tCarnival2016_Food_Stc[7]["Type"]			if Task_ChkStcValue(nEventGuess1,nTypeGuess1,"==",2) then		if Task_StcInterval(nEventGuess1,nTypeGuess1,1,4) then			Task_SetStatistic(nEventGuess1,nTypeGuess1,0,1)		end	end		if Task_ChkStcValue(nEventGuess2,nTypeGuess2,"==",2) then		if Task_StcInterval(nEventGuess2,nTypeGuess2,1,4) then			Task_SetStatistic(nEventGuess2,nTypeGuess2,0,1)		end	end		if Task_ChkStcValue(nEventGuess3,nTypeGuess3,"==",2) then		if Task_StcInterval(nEventGuess3,nTypeGuess3,1,4) then			Task_SetStatistic(nEventGuess3,nTypeGuess3,0,1)		end	end			if Task_ChkStcValue(nEventGuess1,nTypeGuess1,"~=",2) then		return false	end		if Task_ChkStcValue(nEventGuess2,nTypeGuess2,"~=",2) then		return false	end		if Task_ChkStcValue(nEventGuess3,nTypeGuess3,"~=",2) then		return false	end		return trueend--选项：好吧，来一份--功能：玩家品尝糖果function Carnival2016_Food_HaveATaste(nNpcId)	if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-1")		return	end		--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-4")		return	end		--等级不满足	if not User_JudgeLevelAndMetempsychosis(tCarnival2016_Food_Cont["MinLevel"],tCarnival2016_Food_Cont["MinMete"]) then		LinkNpcGossipFunc_New(nNpcId,"1-3")		return	end	--吃	local nEat = tCarnival2016_Food_Cont["NpcToStc"]["Eat"][nNpcId]	local nEventEat = tCarnival2016_Food_Stc[nEat]["Event"]	local nTypeEat = tCarnival2016_Food_Stc[nEat]["Type"]		--试	local nTry = tCarnival2016_Food_Cont["NpcToStc"]["Try"][nNpcId]	local nEventTry = tCarnival2016_Food_Stc[nTry]["Event"]	local nTypeTry = tCarnival2016_Food_Stc[nTry]["Type"]		--隔天了	if Task_StcInterval(nEventTry,nTypeTry,1,4) then		Task_SetStatistic(nEventTry,nTypeTry,0,1)		Task_SetStcTimestamp(nEventTry,nTypeTry,0)	end	--隔天了	if Task_StcInterval(nEventEat,nTypeEat,1,4) then		Task_SetStatistic(nEventEat,nTypeEat,0,1)		Task_SetStcTimestamp(nEventEat,nTypeEat,0)	end		--有吃过，且没有超过30秒	if Task_ChkStcValue(nEventEat,nTypeEat,">",0) and not Task_StcInterval(nEventEat,nTypeEat,30,0) then		LinkNpcGossipFunc_New(nNpcId,"2-3")		return	end		--有尝过，且没超过30s	if Task_ChkStcValue(nEventTry,nTypeTry,">",0) then				if not Task_StcInterval(nEventTry,nTypeTry,30,0) then			--User_TalkChannel2005("有尝过，未超过时间")			LinkNpcGossipFunc_New(nNpcId,"2-3")			return		end			end		--如果已经尝试成功，则不需要记为1	if Task_ChkStcValue(nEventTry,nTypeTry,"~=",2) then		Task_SetStatistic(nEventTry,nTypeTry,1,1)	end		Task_SetStcTimestamp(nEventTry,nTypeTry,0)		local nExAc = tCarnival2016_Food_Cont["ExploreAc"]		User_SetExplore(2,tCarnival2016_Food_Text["Explorer"],nExAc,"Carnival2016_Food_TasteSucc</N>"..nNpcId)	end--接品尝读条成功--品尝成功function Carnival2016_Food_TasteSucc(nNpcId,nNowUserId)	local nUserId = nNowUserId or Get_UserId()	if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-1")		return	end		--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-4")		return	end		--等级不满足	if not User_JudgeLevelAndMetempsychosis(tCarnival2016_Food_Cont["MinLevel"],tCarnival2016_Food_Cont["MinMete"],nUserId) then		LinkNpcGossipFunc_New(nNpcId,"1-3")		return	end		--吃	local nEat = tCarnival2016_Food_Cont["NpcToStc"]["Eat"][nNpcId]	local nEventEat = tCarnival2016_Food_Stc[nEat]["Event"]	local nTypeEat = tCarnival2016_Food_Stc[nEat]["Type"]		--试	local nTry = tCarnival2016_Food_Cont["NpcToStc"]["Try"][nNpcId]	local nEventTry = tCarnival2016_Food_Stc[nTry]["Event"]	local nTypeTry = tCarnival2016_Food_Stc[nTry]["Type"]		--隔天了	if Task_StcInterval(nEventTry,nTypeTry,1,4,nUserId) then		Task_SetStatistic(nEventTry,nTypeTry,0,1,nUserId)		Task_SetStcTimestamp(nEventTry,nTypeTry,0,nUserId)	end	--隔天了	if Task_StcInterval(nEventEat,nTypeEat,1,4,nUserId) then		Task_SetStatistic(nEventEat,nTypeEat,0,1,nUserId)		Task_SetStcTimestamp(nEventEat,nTypeEat,0,nUserId)	end		--有吃过，且没有超过30秒	if Task_ChkStcValue(nEventEat,nTypeEat,">",0,nUserId) and not Task_StcInterval(nEventEat,nTypeEat,30,0,nUserId) then		LinkNpcGossipFunc_New(nNpcId,"2-3")		return	end		--有尝过，且没超过30s	if Task_ChkStcValue(nEventTry,nEventTry,">",0,nUserId) and not Task_StcInterval(nEventTry,nEventTry,30,0,nUserId) then		LinkNpcGossipFunc_New(nNpcId,"2-3")		return	end			local flat,tItem = Probabil_RandomAward(tCarnival2016_Food_Prob["Guess"],1)	local nSel = tItem[1]["tAward"][1]["Item_1"]		local nToItemId = tCarnival2016_Food_Cont["NpcRanToItem"][nNpcId][nSel]	Carnival2016_Food_ExraAct(nToItemId,nUserId)		Sys_MsgBox(tCarnival2016_Food_Text["FoodTip"][nToItemId],"Carnival2016_Food_GotoGossip</N>"..nNpcId.."</N>"..nSel,"NULL",nUserId)end--function Carnival2016_Food_GotoGossip(nNpcId,nSel)		if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-1")		return	end		--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-4")		return	end		if nSel == 1 then		tNpcGossip[nNpcId]["OptionFunc221"] = "Carnival2016_Food_GuessRight</N>"..nNpcId		tNpcGossip[nNpcId]["OptionFunc222"] = "Carnival2016_Food_GuessErr</N>"..nNpcId		tNpcGossip[nNpcId]["OptionFunc223"] = "Carnival2016_Food_GuessErr</N>"..nNpcId	elseif nSel == 2 then		tNpcGossip[nNpcId]["OptionFunc221"] = "Carnival2016_Food_GuessErr</N>"..nNpcId		tNpcGossip[nNpcId]["OptionFunc222"] = "Carnival2016_Food_GuessRight</N>"..nNpcId		tNpcGossip[nNpcId]["OptionFunc223"] = "Carnival2016_Food_GuessErr</N>"..nNpcId	else		tNpcGossip[nNpcId]["OptionFunc221"] = "Carnival2016_Food_GuessErr</N>"..nNpcId		tNpcGossip[nNpcId]["OptionFunc222"] = "Carnival2016_Food_GuessErr</N>"..nNpcId		tNpcGossip[nNpcId]["OptionFunc223"] = "Carnival2016_Food_GuessRight</N>"..nNpcId	end		LinkNpcGossipFunc_New(nNpcId,"2-2")end--选项：猜测是...--猜测错误function Carnival2016_Food_GuessErr(nNpcId)		if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-1")		return	end		--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-4")		return	end		--吃	local nEat = tCarnival2016_Food_Cont["NpcToStc"]["Eat"][nNpcId]	local nEventEat = tCarnival2016_Food_Stc[nEat]["Event"]	local nTypeEat = tCarnival2016_Food_Stc[nEat]["Type"]		--试	local nTry = tCarnival2016_Food_Cont["NpcToStc"]["Try"][nNpcId]	local nEventTry = tCarnival2016_Food_Stc[nTry]["Event"]	local nTypeTry = tCarnival2016_Food_Stc[nTry]["Type"]		if Task_ChkStcValue(nEventTry,nTypeTry,"~=",2) then		Task_SetStatistic(nEventTry,nTypeTry,1,1)	end		Task_SetStcTimestamp(nEventTry,nTypeTry,0)		LinkNpcGossipFunc_New(nNpcId,"2-4")end--选项：猜测是--猜测正确function Carnival2016_Food_GuessRight(nNpcId)	if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-1")		return	end		--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-4")		return	end		--吃	local nEat = tCarnival2016_Food_Cont["NpcToStc"]["Eat"][nNpcId]	local nEventEat = tCarnival2016_Food_Stc[nEat]["Event"]	local nTypeEat = tCarnival2016_Food_Stc[nEat]["Type"]		--试	local nTry = tCarnival2016_Food_Cont["NpcToStc"]["Try"][nNpcId]	local nEventTry = tCarnival2016_Food_Stc[nTry]["Event"]	local nTypeTry = tCarnival2016_Food_Stc[nTry]["Type"]		Task_SetStatistic(nEventTry,nTypeTry,2,1)	Task_SetStcTimestamp(nEventTry,nTypeTry,0)		LinkNpcGossipFunc_New(nNpcId,"2-5")end--试吃食物function Carnival2016_Food_UseItem(nItemId)		if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		User_TalkChannel2005(tCarnival2016_Food_Text["NoTime"])		return	end		local sLog = string.format(tCarnival2016_Food_Log["TimeDel"],nItemId)	--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		if not Item_ChkItem(nItemId) then			return		end		if not Item_DelAllItemByType(nItemId) then			return		end		Sys_SaveActionFestivalLog(sLog)		User_TalkChannel2005(tCarnival2016_Food_Text["AfterTime"])		return	end		local nEvent = tCarnival2016_Food_Cont["ItemToStc"]["Event"]	local nTypeEat = tCarnival2016_Food_Cont["ItemToStc"]["TypeEat"][nItemId]	local nTypeTry = tCarnival2016_Food_Cont["ItemToStc"]["TypeTry"][nItemId]			--隔天了	if Task_StcInterval(nEvent,nTypeTry,1,4) then		Task_SetStatistic(nEvent,nTypeTry,0,1)		Task_SetStcTimestamp(nEvent,nTypeTry,0)	end	--隔天了	if Task_StcInterval(nEvent,nTypeEat,1,4) then		Task_SetStatistic(nEvent,nTypeEat,0,1)		Task_SetStcTimestamp(nEvent,nTypeEat,0)	end		--有吃过，且没有超过30秒	if Task_ChkStcValue(nEvent,nTypeEat,">",0) and not Task_StcInterval(nEvent,nTypeEat,30,0) then		Sys_MsgBox(tCarnival2016_Food_Text["EatToo"])		return	end		--有尝过，且没超过30s	if Task_ChkStcValue(nEvent,nTypeTry,">",0) and not Task_StcInterval(nEvent,nTypeTry,30,0) then		Sys_MsgBox(tCarnival2016_Food_Text["EatToo"])		return	end		--当天已经吃了50个了	local nMaxToday = tCarnival2016_Food_Cont["TodayMax"]		if Task_ChkStcValue(nEvent,nTypeEat,">=",nMaxToday) then		Sys_MsgBox(tCarnival2016_Food_Text["EatMoreThen"][nItemId])		return	end		if not Item_ChkItem(nItemId) then		return	end		Task_AddStatistic(nEvent,nTypeEat,1,1)	Task_SetStcTimestamp(nEvent,nTypeEat,0)		if not Item_DelItem(nItemId) then		return	end	Sys_SaveActionFestivalLog(sLog)		local nExAc = tCarnival2016_Food_Cont["ExploreAc"]	User_SetExplore(2,tCarnival2016_Food_Text["Explorer"],nExAc,"Carnival2016_Food_EatSucc</N>"..nItemId)end--吃食物成功function Carnival2016_Food_EatSucc(nItemId,nNowUserId)	local nUserId = nNowUserId or Get_UserId()	if Sys_ChkFullTime(tCarnival2016_Food_Cont["BeforeActivityTime"]) then		User_TalkChannel2005(tCarnival2016_Food_Text["NoTime"],nUserId)		return	end	local sLog = string.format(tCarnival2016_Food_Log["TimeDel"],nItemId)	--活动时间后	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		if not Item_ChkItem(nItemId,1,0,nUserId) and not Item_DelAllItemByType(nItemId,nUserId) then			return		end		Sys_SaveActionFestivalLog(sLog,nUserId)		User_TalkChannel2005(tCarnival2016_Food_Text["AfterTime"],nUserId)		return	end		local nEvent = tCarnival2016_Food_Cont["ItemToStc"]["Event"]	local nTypeEat = tCarnival2016_Food_Cont["ItemToStc"]["TypeEat"][nItemId]		Carnival2016_Food_ExraAct(nItemId,nUserId)	User_TalkChannel2005(tCarnival2016_Food_Text["FoodTip"][nItemId],nUserId)end--品尝/吃食物额外反应function Carnival2016_Food_ExraAct(nItemId,nNowUserId)	local nUserId = nNowUserId or Get_UserId()	if tCarnival2016_Food_Effect[nItemId] ~= "" then		User_EffectAdd(tCarnival2016_Food_Effect["Self"],tCarnival2016_Food_Effect[nItemId],nUserId)	end		if tCarnival2016_Food_Cont["Status"][nItemId] ~= nil then		local nStatus = tCarnival2016_Food_Cont["Status"][nItemId]["Status"]		local nPower = tCarnival2016_Food_Cont["Status"][nItemId]["Power"]		local nSec = tCarnival2016_Food_Cont["Status"][nItemId]["Sec"]		local nTimes = tCarnival2016_Food_Cont["Status"][nItemId]["Times"]		local nRemainTime = tCarnival2016_Food_Cont["Status"][nItemId]["RemainTime"]		local nEndTime = tCarnival2016_Food_Cont["Status"][nItemId]["EndTime"]		local nRecordable = tCarnival2016_Food_Cont["Status"][nItemId]["Recordable"]		-- local nUserId = Get_UserId()		User_AddRoleStatus(nStatus,nPower,nSec,nTimes,nRemainTime,nEndTime,nRecordable,0,0,nUserId)	end			if tCarnival2016_Food_ItemFunc[nItemId] == nil then		return	end		local fun = tCarnival2016_Food_ItemFunc[nItemId]["Func"]	local tParam1 = tCarnival2016_Food_ItemFunc[nItemId]["Param"]	if nItemId ~= 3000460 then		fun(tParam1,nUserId)	else		User_TransForm(11630,0,7,30,nUserId)	endendfunction Carnival2016_Food_Split(s, p)    local rt = {}    string.gsub(s, '[^'..p..']+', function(w) table.insert(rt,tonumber(w)) end )    return rtend--系统自检function Carnival2016_Food_SysMapDrop()	--非活动时间内	if not Sys_ChkFullTime(tCarnival2016_Food_Cont["ActivityTime"]) then		return	end		local nMin = tonumber(os.date("%M"))		if tCarnival2016_Food_Cont["MapDropItemId"][nMin] == nil then		return	end		local nItemId = tCarnival2016_Food_Cont["MapDropItemId"][nMin]	local nMapId = tCarnival2016_Food_Cont["MapDrop"]["MapId"]	local nPosX = tCarnival2016_Food_Cont["MapDrop"]["PosX"]	local nPosY = tCarnival2016_Food_Cont["MapDrop"]["PosY"]	local nCellx = tCarnival2016_Food_Cont["MapDrop"]["Cellx"]	local nCelly = tCarnival2016_Food_Cont["MapDrop"]["Celly"]	local nItemNum = tCarnival2016_Food_Cont["MapDrop"]["ItemNum"]	local nExistTime = tCarnival2016_Food_Cont["MapDrop"]["ExistTime"]		Map_DropMultiItems(nMapId, nItemId, nPosX, nPosY, nCellx, nCelly, nItemNum, nExistTime)		end-----------------------------------------------------NPC模块-------------------------------------------------tNpcFace[2186] = 90tNpcGossip[15364] = tNpcGossip[15364] or DefaultNpc:new{}tNpcGossip[15364]["OptionHidden"] = 1

